item.command:
/bin/bash -lc "curl -s 'https://www.encodeproject.org/search/?type=Experiment&assay_title=DNase-seq&assembly=GRCh38&status=released&format=json&limit=all&field=accession&field=analyses.pipeline_version&field=analyses.assembly&field=analyses.files' | python3 -c \"import json,sys; d=json.load(sys.stdin); g=d['@graph']; print('exps',len(g)); 
for e in g:
    pvs=set((a.get('pipeline_version'),a.get('assembly')) for a in e.get('analyses',[]));
    if any(str(p).startswith('3.0.0') for p,a in pvs): print(e['accession'], pvs)\" | head -c 5000"

